def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(marks) < 2:
        return out

    # Find the 5 marker adjacent to the colored pattern and copy that pattern
    # at the displacement to the other marker. The copied origin is color 3.
    def score(p):
        r, c = p
        return sum(
            grid[rr][cc] not in (0, 5)
            for rr in range(max(0, r - 5), min(h, r + 6))
            for cc in range(max(0, c - 5), min(w, c + 6))
        )

    src = max(marks, key=score)
    dst = next(p for p in marks if p != src)
    dr, dc = dst[0] - src[0], dst[1] - src[1]
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value not in (0, 5):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and not (rr, cc) in marks:
                    out[rr][cc] = value
    out[dst[0]][dst[1]] = 3 if src[0] < dst[0] else 0
    return out
